import { randomUUID } from "node:crypto";
import { DomainError } from "../domain/errors";
import { FLOW, Order, type OrderLine, type OrderState } from "../domain/order";
import { Product } from "../domain/product";
import type { OrderRepository, ProductRepository } from "./ports";

export interface StockLevel {
  productId: string;
  name: string;
  available: number;
  reserved: number;
}

const ALL_STATES: readonly string[] = [...FLOW, "cancelled"];

export class OrderService {
  constructor(
    private readonly products: ProductRepository,
    private readonly orders: OrderRepository,
  ) {}

  addProduct(id: string, name: string, stock: number): Product {
    if (!id || !name) throw new DomainError("invalid", "id and name are required");
    if (this.products.get(id)) throw new DomainError("invalid", `product ${id} already exists`);
    const product = new Product(id, name, stock);
    this.products.save(product);
    return product;
  }

  stockLevels(): StockLevel[] {
    return this.products.list().map((p) => this.level(p));
  }

  stockLevel(productId: string): StockLevel {
    return this.level(this.requireProduct(productId));
  }

  placeOrder(customerId: string, items: readonly OrderLine[]): Order {
    if (!customerId) throw new DomainError("invalid", "customerId is required");
    if (items.length === 0) throw new DomainError("invalid", "order needs at least one item");

    const merged = new Map<string, number>();
    for (const item of items) {
      if (!item || !item.productId || !Number.isInteger(item.quantity) || item.quantity <= 0) {
        throw new DomainError("invalid", "each item needs a productId and a positive integer quantity");
      }
      merged.set(item.productId, (merged.get(item.productId) ?? 0) + item.quantity);
    }

    // Validate everything first so a failure reserves nothing.
    for (const [productId, quantity] of merged) {
      const product = this.requireProduct(productId);
      if (!product.canReserve(quantity)) {
        throw new DomainError("insufficient_stock", `insufficient stock for product ${productId}`);
      }
    }
    const lines: OrderLine[] = [];
    for (const [productId, quantity] of merged) {
      const product = this.requireProduct(productId);
      product.reserve(quantity);
      this.products.save(product);
      lines.push({ productId, quantity });
    }
    const order = new Order(randomUUID(), customerId, lines, new Date());
    this.orders.save(order);
    return order;
  }

  getOrder(id: string): Order {
    const order = this.orders.get(id);
    if (!order) throw new DomainError("not_found", `order ${id} not found`);
    return order;
  }

  listOrders(state?: string): Order[] {
    if (state !== undefined && !ALL_STATES.includes(state)) {
      throw new DomainError("invalid", `unknown state ${state}`);
    }
    return this.orders.list(state as OrderState | undefined);
  }

  advance(id: string, next: OrderState): Order {
    const order = this.getOrder(id);
    order.advanceTo(next);
    if (next === "shipped") {
      for (const line of order.lines) {
        const product = this.requireProduct(line.productId);
        product.consumeReserved(line.quantity);
        this.products.save(product);
      }
    }
    this.orders.save(order);
    return order;
  }

  cancel(id: string): Order {
    const order = this.getOrder(id);
    order.cancel();
    for (const line of order.lines) {
      const product = this.requireProduct(line.productId);
      product.release(line.quantity);
      this.products.save(product);
    }
    this.orders.save(order);
    return order;
  }

  private requireProduct(id: string): Product {
    const product = this.products.get(id);
    if (!product) throw new DomainError("not_found", `product ${id} not found`);
    return product;
  }

  private level(p: Product): StockLevel {
    return { productId: p.id, name: p.name, available: p.availableStock, reserved: p.reservedStock };
  }
}

